-- Required whole Buried Sea content; guarded staged payload, disabled until complete activation.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_tbsc_achievement_categories`;
CREATE TEMPORARY TABLE `_tbsc_achievement_categories` LIKE `achievement_categories`;
DROP TEMPORARY TABLE IF EXISTS `_tbsc_achievements`;
CREATE TEMPORARY TABLE `_tbsc_achievements` LIKE `achievements`;
DROP TEMPORARY TABLE IF EXISTS `_tbsc_achievement_components`;
CREATE TEMPORARY TABLE `_tbsc_achievement_components` LIKE `achievement_components`;
DROP TEMPORARY TABLE IF EXISTS `_tbsc_achievement_category_associations`;
CREATE TEMPORARY TABLE `_tbsc_achievement_category_associations` LIKE `achievement_category_associations`;
DROP TEMPORARY TABLE IF EXISTS `_tbsc_guard`;
CREATE TEMPORARY TABLE `_tbsc_guard`(ok TINYINT NOT NULL CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
SET @tbsc_ok=
(COALESCE(@buriedsea_whole_batch_reviewed,0)=1)
 AND ((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN(CONVERT(0x616368696576656d656e745f63617465676f72696573 USING utf8mb4),CONVERT(0x616368696576656d656e7473 USING utf8mb4),CONVERT(0x616368696576656d656e745f636f6d706f6e656e7473 USING utf8mb4),CONVERT(0x616368696576656d656e745f63617465676f72795f6173736f63696174696f6e73 USING utf8mb4)) AND ENGINE='InnoDB')=4)
 AND (NOT EXISTS(SELECT 1 FROM `achievement_categories` a JOIN `_tbsc_achievement_categories` e ON a.`id`<=>e.`id` WHERE NOT(a.`id`<=>e.`id` AND a.`parent_id`<=>e.`parent_id` AND a.`sequence`<=>e.`sequence` AND a.`name`<=>e.`name` AND a.`description`<=>e.`description` AND a.`icon`<=>e.`icon`)))
 AND (NOT EXISTS(SELECT 1 FROM `achievements` a JOIN `_tbsc_achievements` e ON a.`id`<=>e.`id` WHERE NOT(a.`id`<=>e.`id` AND a.`name`<=>e.`name` AND a.`description`<=>e.`description` AND a.`icon_id`<=>e.`icon_id` AND a.`points`<=>e.`points` AND a.`has_reward`<=>e.`has_reward` AND a.`client_flag`<=>e.`client_flag` AND a.`version`<=>e.`version` AND a.`reset_on_version_change`<=>e.`reset_on_version_change` AND a.enabled IN(0,1))))
 AND (NOT EXISTS(SELECT 1 FROM `achievement_components` a JOIN `_tbsc_achievement_components` e ON a.`achievement_id`<=>e.`achievement_id` AND a.`component_type`<=>e.`component_type` AND a.`component_id`<=>e.`component_id` WHERE NOT(a.`achievement_id`<=>e.`achievement_id` AND a.`component_type`<=>e.`component_type` AND a.`sequence`<=>e.`sequence` AND a.`component_id`<=>e.`component_id` AND a.`name`<=>e.`name` AND a.`description`<=>e.`description`)))
 AND (NOT EXISTS(SELECT 1 FROM `achievement_category_associations` a JOIN `_tbsc_achievement_category_associations` e ON a.`achievement_id`<=>e.`achievement_id` AND a.`category_id`<=>e.`category_id` WHERE NOT(a.`category_id`<=>e.`category_id` AND a.`sequence`<=>e.`sequence` AND a.`achievement_id`<=>e.`achievement_id` AND a.`display_text`<=>e.`display_text`)));
COMMIT;
