INSERT INTO `_tbsc_guard`VALUES(COALESCE(@tbsc_ok,0));
INSERT INTO `achievement_categories`(`id`,`parent_id`,`sequence`,`name`,`description`,`icon`)SELECT e.`id`,e.`parent_id`,e.`sequence`,e.`name`,e.`description`,e.`icon` FROM `_tbsc_achievement_categories` e WHERE @tbsc_ok=1 AND NOT EXISTS(SELECT 1 FROM `achievement_categories` a WHERE a.`id`<=>e.`id`);
INSERT INTO `achievements`(`id`,`name`,`description`,`icon_id`,`points`,`has_reward`,`client_flag`,`version`,`reset_on_version_change`,`enabled`)SELECT e.`id`,e.`name`,e.`description`,e.`icon_id`,e.`points`,e.`has_reward`,e.`client_flag`,e.`version`,e.`reset_on_version_change`,e.`enabled` FROM `_tbsc_achievements` e WHERE @tbsc_ok=1 AND NOT EXISTS(SELECT 1 FROM `achievements` a WHERE a.`id`<=>e.`id`);
INSERT INTO `achievement_components`(`achievement_id`,`component_type`,`sequence`,`component_id`,`name`,`description`)SELECT e.`achievement_id`,e.`component_type`,e.`sequence`,e.`component_id`,e.`name`,e.`description` FROM `_tbsc_achievement_components` e WHERE @tbsc_ok=1 AND NOT EXISTS(SELECT 1 FROM `achievement_components` a WHERE a.`achievement_id`<=>e.`achievement_id` AND a.`component_type`<=>e.`component_type` AND a.`component_id`<=>e.`component_id`);
INSERT INTO `achievement_category_associations`(`category_id`,`sequence`,`achievement_id`,`display_text`)SELECT e.`category_id`,e.`sequence`,e.`achievement_id`,e.`display_text` FROM `_tbsc_achievement_category_associations` e WHERE @tbsc_ok=1 AND NOT EXISTS(SELECT 1 FROM `achievement_category_associations` a WHERE a.`achievement_id`<=>e.`achievement_id` AND a.`category_id`<=>e.`category_id`);
